{
  "steps": [
    {
      "type": "tool",
      "name": "quote",
      "output_key": "quote",
      "tool": "market_quote",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "path",
      "output_key": "path",
      "tool": "candlesticks",
      "args": {
        "symbol": "{{question}}",
        "hours_back": 0.5,
        "interval": "1m"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "tape",
      "output_key": "tape",
      "tool": "recent_trades",
      "args": {
        "symbol": "{{question}}",
        "minutes_back": 3,
        "limit": 20
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "funding",
      "output_key": "funding",
      "tool": "funding_rate",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "others",
      "output_key": "others",
      "tool": "cross_asset",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "tool",
      "name": "summary",
      "output_key": "summary",
      "tool": "state_summary",
      "args": {
        "symbol": "{{question}}"
      },
      "fail_ok": true
    },
    {
      "type": "prompt",
      "name": "predict",
      "output_key": "forecast",
      "prompt": "Symbol: {{question}}\nCalendar: {{context}}\nState: {{summary.summary}}\nLast close: {{quote}}\nMinute bars, last 30m: {{path}}\nRecent prints: {{tape}}\nFunding: {{funding}}\nThe other majors: {{others}}",
      "tools": [],
      "max_tool_iterations": 6,
      "questions": {
        "move": {
          "type": "score",
          "instructions": "How many basis points the spot price moves over the next minute, from the last complete one-minute close shown. Positive is up. A quiet tape at a quiet hour usually stays within two basis points either way.",
          "criteria": [
            "down 10 bps or more",
            "down 4 to 9 bps",
            "down about 2 bps",
            "unchanged, within a basis point either way",
            "up about 2 bps",
            "up 4 to 9 bps",
            "up 10 bps or more"
          ],
          "values": [
            -15,
            -6,
            -2,
            0,
            2,
            6,
            15
          ]
        }
      },
      "answers": {
        "delta_bps": {
          "from": "move",
          "as": "mean"
        },
        "half_width_bps": {
          "from": "move",
          "as": "half_range",
          "coverage": 0.6,
          "min": 1
        },
        "confidence": {
          "from": "move",
          "as": "confidence"
        },
        "driver": {
          "as": "const",
          "value": "the expectation of the move distribution"
        },
        "falsifier": {
          "as": "const",
          "value": "a close outside the quoted band when the minute prints"
        }
      }
    }
  ]
}

